content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background-color: #1a1a1a;
  color: #ffffff;
  overflow: hidden;
  width: 100vw;
  height: 100vh;
}

.app-container {
  position: relative;
  width: 100vw;
  height: 100vh;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.header {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  padding: 20px;
  background: linear-gradient(to bottom, rgba(0, 0, 0, 0.8), rgba(0, 0, 0, 0));
  z-index: 10;
  display: flex;
  flex-direction: column;
  align-items: center;
  pointer-events: none;
}

.title {
  font-size: 1.8rem;
  font-weight: 700;
  margin-bottom: 8px;
  text-shadow: 0 2px 4px rgba(0, 0, 0, 0.5);
  letter-spacing: 0.05em;
}

.instruction {
  font-size: 0.95rem;
  color: #cccccc;
  background-color: rgba(0, 0, 0, 0.6);
  padding: 6px 16px;
  border-radius: 20px;
  backdrop-filter: blur(4px);
  border: 1px solid rgba(255, 255, 255, 0.1);
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.2);
}

.canvas-container {
  width: 100%;
  height: 100%;
  position: absolute;
  top: 0;
  left: 0;
  cursor: grab;
}

.canvas-container:active {
  cursor: grabbing;
}

import React, { useEffect, useRef } from 'react';
import * as THREE from 'three';
import './index.css';

export default function App() {
  const mountRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const currentMount = mountRef.current;
    if (!currentMount) return;

    // シーン、カメラ、レンダラーの初期化
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x1a1a1a);

    const camera = new THREE.PerspectiveCamera(
      60,
      currentMount.clientWidth / currentMount.clientHeight,
      0.1,
      1000
    );
    camera.position.z = 5;

    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(currentMount.clientWidth, currentMount.clientHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    currentMount.appendChild(renderer.domElement);

    // ライティング
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.7);
    scene.add(ambientLight);

    const directionalLight = new THREE.DirectionalLight(0xffffff, 1.2);
    directionalLight.position.set(5, 5, 5);
    scene.add(directionalLight);

    const pointLight = new THREE.PointLight(0x3b82f6, 2, 50);
    pointLight.position.set(-5, -5, -5);
    scene.add(pointLight);

    // キューブの作成（各面に異なる色を設定して立体感を出す）
    const geometry = new THREE.BoxGeometry(2, 2, 2);

    // 6つの面に異なる美しいカラーマテリアルを適用
    const materials = [
      new THREE.MeshStandardMaterial({ color: 0xef4444, roughness: 0.3, metalness: 0.2 }), // 右: 赤
      new THREE.MeshStandardMaterial({ color: 0xf97316, roughness: 0.3, metalness: 0.2 }), // 左: オレンジ
      new THREE.MeshStandardMaterial({ color: 0x10b981, roughness: 0.3, metalness: 0.2 }), // 上: 緑
      new THREE.MeshStandardMaterial({ color: 0x3b82f6, roughness: 0.3, metalness: 0.2 }), // 下: 青
      new THREE.MeshStandardMaterial({ color: 0x8b5cf6, roughness: 0.3, metalness: 0.2 }), // 前: 紫
      new THREE.MeshStandardMaterial({ color: 0xec4899, roughness: 0.3, metalness: 0.2 }), // 後: ピンク
    ];

    const cube = new THREE.Mesh(geometry, materials);
    scene.add(cube);

    // ワイヤーフレーム用のオーバーレイ（デザインアクセント）
    const wireframeGeometry = new THREE.WireframeGeometry(geometry);
    const wireframeMaterial = new THREE.LineBasicMaterial({ color: 0xffffff, linewidth: 2, transparent: true, opacity: 0.15 });
    const wireframe = new THREE.LineSegments(wireframeGeometry, wireframeMaterial);
    cube.add(wireframe);

    // インタラクション（マウス・タッチ操作）の状態管理
    let isDragging = false;
    let previousMousePosition = { x: 0, y: 0 };
    let targetRotationVelocity = { x: 0.005, y: 0.008 }; // 自動回転の初期速度
    let currentRotationVelocity = { x: 0.005, y: 0.008 };

    const onPointerDown = (e: PointerEvent) => {
      isDragging = true;
      previousMousePosition = { x: e.clientX, y: e.clientY };
      currentTarget.setPointerCapture(e.pointerId);
    };

    const onPointerMove = (e: PointerEvent) => {
      if (!isDragging) return;

      const deltaX = e.clientX - previousMousePosition.x;
      const deltaY = e.clientY - previousMousePosition.y;

      // ドラッグ操作による回転速度の設定
      targetRotationVelocity.y = deltaX * 0.005;
      targetRotationVelocity.x = deltaY * 0.005;

      cube.rotation.y += targetRotationVelocity.y;
      cube.rotation.x += targetRotationVelocity.x;

      previousMousePosition = { x: e.clientX, y: e.clientY };
    };

    const onPointerUp = (e: PointerEvent) => {
      isDragging = false;
      try {
        currentMount.releasePointerCapture(e.pointerId);
      } catch (err) {
        // 無視
      }
    };

    const currentTarget = currentMount;
    currentTarget.addEventListener('pointerdown', onPointerDown);
    currentTarget.addEventListener('pointermove', onPointerMove);
    currentTarget.addEventListener('pointerup', onPointerUp);
    currentTarget.addEventListener('pointercancel', onPointerUp);

    // リサイズ処理
    const handleResize = () => {
      if (!currentMount) return;
      const width = currentMount.clientWidth;
      const height = currentMount.clientHeight;

      camera.aspect = width / height;
      camera.updateProjectionMatrix();
      renderer.setSize(width, height);
    };

    window.addEventListener('resize', handleResize);

    // アニメーションループ
    let animationFrameId: number;
    const animate = () => {
      animationFrameId = requestAnimationFrame(animate);

      if (!isDragging) {
        // ドラッグしていない時は少しずつ慣性で回転を減衰させるか、微小回転を続ける
        currentRotationVelocity.x += (0.002 - currentRotationVelocity.x) * 0.05;
        currentRotationVelocity.y += (0.004 - currentRotationVelocity.y) * 0.05;

        cube.rotation.x += currentRotationVelocity.x;
        cube.rotation.y += currentRotationVelocity.y;
      } else {
        // ドラッグ中は現在の速度を保持・スムーズ化
        currentRotationVelocity.x += (targetRotationVelocity.x - currentRotationVelocity.x) * 0.2;
        currentRotationVelocity.y += (targetRotationVelocity.y - currentRotationVelocity.y) * 0.2;

        // 慣性をゼロに近づけておく
        targetRotationVelocity.x *= 0.9;
        targetRotationVelocity.y *= 0.9;
      }

      renderer.render(scene, camera);
    };

    animate();

    // クリーンアップ
    return () => {
      window.removeEventListener('resize', handleResize);
      currentTarget.removeEventListener('pointerdown', onPointerDown);
      currentTarget.removeEventListener('pointermove', onPointerMove);
      currentTarget.removeEventListener('pointerup', onPointerUp);
      currentTarget.removeEventListener('pointercancel', onPointerUp);

      cancelAnimationFrame(animationFrameId);
      if (currentMount && renderer.domElement) {
        currentMount.removeChild(renderer.domElement);
      }
      renderer.dispose();
      geometry.dispose();
      materials.forEach(mat => mat.dispose());
      wireframeGeometry.dispose();
      wireframeMaterial.dispose();
    };
  }, []);

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="title">3D 立方体ビューアー</h1>
        <p className="instruction">マウスまたは指でドラッグして立方体を回転させてください</p>
      </header>
      <div ref={mountRef} className="canvas-container" />
    </div>
  );
}
